------------ import ------------
local UIEventProxy = CS.Engine.UI.UIEventProxy
local KTool = CS.Engine.Lib.KTool
local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds

------------ import ------------

------------ define ------------
local DefaultCD = {
    Click = 1,
    Toast = 1,
}
------------ define ------------


---@class CommonCDBtn
local CommonCDBtn = Class("CommonCDBtn")
function CommonCDBtn:__init()
    self.timer = nil
    self.isBtnInCD = false
    self.isToastInCD = false
    self.clickCD = nil
    self.toastCD = nil
    self.toast = nil
    self.clickCo = nil
    self.toastCo = nil
end

function CommonCDBtn:__delete()
    self.controller = nil
    self.timer = nil
    self.isBtnInCD = nil
    self.isToastInCD = nil
    self.clickCD = nil
    self.toastCD = nil
    self.toast = nil
    self.clickCo = nil
    self.toastCo = nil
end

---SetCallBack
---设置单击回调函数
---@param cb fun():void 未进入冷却时点击触发的事件
---@param clickCD number 点击间隔 默认三秒
---@param cbCDOver fun():void 冷却完成触发的事件(如按钮按下变灰，三秒后亮起)
---@param toastCD number 点击进入冷却时间的飘字间隔 默认三秒
---@param toast string 点击进入冷却时间的飘字内容 不传时在点击进入冷却时再次点击不会有飘字
function CommonCDBtn:SetCallBack(cb, clickCD, cbCDOver, toastCD, toast)
    self.__callback = cb
    self.__callbackCDOver = cbCDOver
    self.clickCD = isNull(clickCD) and DefaultCD.Click or clickCD
    self.toastCD = isNull(toastCD) and DefaultCD.Toast or toastCD
    self.toast = toast
end

function CommonCDBtn:Awake()
    UIEventProxy.Create(self.controller.gameObject).onPointerClick = function()
        if self.isBtnInCD then
            if not isNull(self.toast) then
                if isNull(self.toastCo) then
                    self.toastCo = cs_coroutine.start(function ()
                        if self.isToastInCD then

                        else
                            self.isToastInCD = true
                            GameUtils.Toast(self.toast)
                            coroutine.yield(WaitForSeconds(self.toastCD))
                            self.isToastInCD = false
                            cs_coroutine.stop(self.toastCo)
                            self.toastCo = nil
                        end
                    end)
                end
            end
        else
            if isNull(self.clickCo) then
                self.clickCo = cs_coroutine.start(function ()
                    self.isBtnInCD = true
                    if type(self.__callback) == 'function' then
                        self.__callback()
                    end
                    if self.toastCo then--将飘字的冷却重置
                        cs_coroutine.stop(self.toastCo)
                        self.toastCo = nil
                    end
                    coroutine.yield(WaitForSeconds(self.clickCD))
                    if not isNull(self.__callbackCDOver) then
                        if type(self.__callback) == 'function' then
                            self.__callbackCDOver()
                        end
                    end
                    self.isBtnInCD = false
                    cs_coroutine.stop(self.clickCo)
                    self.clickCo = nil
                end)

            end
        end
    end
end

function CommonCDBtn:ResetCD()
    self.isBtnInCD = false
    self.isToastInCD = false
    if self.toastCo then
        cs_coroutine.stop(self.toastCo)
        self.toastCo = nil
    end
    if self.clickCo then
        cs_coroutine.stop(self.clickCo)
        self.clickCo = nil
    end
end

function CommonCDBtn:OnDestroy()
    self:ResetCD()
    --printInfo("======Destroy")
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return CommonCDBtn